}","path":"~/workspace/neon-qbert/src/game-state.ts"}

{"content":"import {
  createSystem,
  Mesh,
  Group,
  BoxGeometry,
  SphereGeometry,
  CylinderGeometry,
  MeshStandardMaterial,
  MeshBasicMaterial,
  Color,
  Vector3,
  AdditiveBlending,
} from '@iwsdk/core';
import {
  state, initCubes, getCube, allCubesComplete, isValidCube, cubePos,
  PYRAMID_ROWS, CUBE_SIZE, PILLAR_HEIGHT, HOP_DURATION, COLOR_SCHEMES,
  emitAudio, emitEffect, saveStats, saveAchievements,
} from './game-state';
import type { EnemyData, ColorScheme, PowerUpType } from './game-state';

function cubeColor(colorState: number, targetState: number, scheme: ColorScheme): number {
  const cs = COLOR_SCHEMES[scheme];
  if (colorState >= targetState) return cs.target;
  if (colorState === 0) return cs.start;
  return cs.mid;
}

const POWER_UP_COLORS: Record<PowerUpType, number> = {
  shield: 0x44aaff,
  scoreboost: 0xffcc00,
  freeze: 0x88ffff,
};

export class GameSystem extends createSystem({}) {
  private cubeGroup!: Group;
  private cubeMeshes: Mesh[] = [];
  private playerMesh!: Mesh;
  private playerGlowMesh!: Mesh;
  private enemyMeshes: Map<number, Group> = new Map();
  private discMeshes: Mesh[] = [];
  private powerUpMeshes: Map<string, Group> = new Map();
  private enemyIdCounter = 0;
  private deathsThisRound = 0;
  private cameraTarget = new Vector3(2, 5.5, 5);
  private cameraLookTarget = new Vector3(0, 1.2, 1.2);

  init() {
    this.cubeGroup = new Group();
    this.scene.add(this.cubeGroup);
    this.buildPyramid();
    this.createPlayer();
    this.createDiscs();
    state.initialized = true;
  }

  private buildPyramid() {
    for (const m of this.cubeMeshes) this.cubeGroup.remove(m);
    this.cubeMeshes = [];
    initCubes();
    const cs = COLOR_SCHEMES[state.colorScheme];
    for (const cube of state.cubes) {
      const pos = cubePos(cube.row, cube.col);
      const geo = new BoxGeometry(CUBE_SIZE, PILLAR_HEIGHT, CUBE_SIZE);
      const mat = new MeshStandardMaterial({
        color: new Color(cs.start),
        emissive: new Color(cs.start),
        emissiveIntensity: 0.3,
        transparent: true,
        opacity: 0.85,
      });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(pos.x, pos.y, pos.z);
      this.cubeGroup.add(mesh);
      this.cubeMeshes.push(mesh);
    }
  }

  private createPlayer() {
    const geo = new SphereGeometry(CUBE_SIZE * 0.35, 16, 16);
    const mat = new MeshStandardMaterial({
      color: new Color(0xffffff),
      emissive: new Color(0xffffff),
      emissiveIntensity: 0.6,
    });
    this.playerMesh = new Mesh(geo, mat);
    const pos = cubePos(0, 0);
    this.playerMesh.position.set(pos.x, pos.y + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.35, pos.z);
    this.playerMesh.visible = false;
    this.scene.add(this.playerMesh);

    // Player glow halo
    const glowGeo = new SphereGeometry(CUBE_SIZE * 0.5, 12, 12);
    const glowMat = new MeshBasicMaterial({
      color: new Color(0xffffff),
      transparent: true,
      opacity: 0.15,
      blending: AdditiveBlending,
    });
    this.playerGlowMesh = new Mesh(glowGeo, glowMat);
    this.playerGlowMesh.visible = false;
    this.scene.add(this.playerGlowMesh);
  }

  private createDiscs() {
    for (let i = 0; i < 2; i++) {
      const geo = new CylinderGeometry(0.2, 0.2, 0.05, 12);
      const mat = new MeshStandardMaterial({
        color: new Color(0xff8800),
        emissive: new Color(0xff8800),
        emissiveIntensity: 0.8,
      });
      const mesh = new Mesh(geo, mat);
      mesh.visible = false;
      this.scene.add(mesh);
      this.discMeshes.push(mesh);
    }
  }

  private positionDiscs() {
    const leftPos = cubePos(3, -1);
    this.discMeshes[0].position.set(leftPos.x - 0.5, leftPos.y, leftPos.z);
    this.discMeshes[0].visible = state.discLeft && state.screen === 'playing';
    const rightPos = cubePos(3, 4);
    this.discMeshes[1].position.set(rightPos.x + 0.5, rightPos.y, rightPos.z);
    this.discMeshes[1].visible = state.discRight && state.screen === 'playing';
  }

  startGame() {
    state.round = 1;
    state.score = 0;
    state.lives = state.difficulty === 'easy' ? 5 : 3;
    state.playerRow = 0;
    state.playerCol = 0;
    state.hopping = false;
    state.roundComplete = false;
    state.gameOver = false;
    state.deathAnimating = false;
    state.enemies = [];
    state.enemySpawnTimer = 0;
    state.timer = 120;
    state.hopsRemaining = state.mode === 'challenge' ? 50 : 999;
    state.totalHops = 0;
    this.deathsThisRound = 0;
    state.discLeft = true;
    state.discRight = true;
    state.discUsed = false;
    state.combo = 0;
    state.maxCombo = 0;
    state.comboTimer = 0;
    state.powerUps = [];
    state.activePowerUp = null;
    state.powerUpSpawnTimer = 0;
    state.shieldActive = false;
    state.freezeActive = false;
    state.scoreBoostActive = false;
    state.roundAnnounceTimer = 2.0;
    state.stats.gamesPlayed++;
    saveStats(state.stats);
    this.buildPyramid();
    this.updateCubeColors();
    this.clearEnemyMeshes();
    this.clearPowerUpMeshes();
    state.screen = 'playing';
  }

  private startRound() {
    state.playerRow = 0;
    state.playerCol = 0;
    state.hopping = false;
    state.roundComplete = false;
    state.enemies = [];
    state.enemySpawnTimer = 0;
    state.discLeft = true;
    state.discRight = true;
    this.deathsThisRound = 0;
    state.combo = 0;
    state.comboTimer = 0;
    state.powerUps = [];
    state.powerUpSpawnTimer = 0;
    state.activePowerUp = null;
    state.shieldActive = false;
    state.freezeActive = false;
    state.scoreBoostActive = false;
    state.roundAnnounceTimer = 2.0;
    this.buildPyramid();
    this.updateCubeColors();
    this.clearEnemyMeshes();
    this.clearPowerUpMeshes();
  }

  private clearEnemyMeshes() {
    for (const [, group] of this.enemyMeshes) {
      this.scene.remove(group);
    }
    this.enemyMeshes.clear();
  }

  private clearPowerUpMeshes() {
    for (const [, group] of this.powerUpMeshes) {
      this.scene.remove(group);
    }
    this.powerUpMeshes.clear();
  }

  updateCubeColors() {
    for (let i = 0; i < state.cubes.length; i++) {
      const cube = state.cubes[i];
      const mesh = this.cubeMeshes[i];
      if (!mesh) continue;
      const col = cubeColor(cube.colorState, cube.targetState, state.colorScheme);
      const mat = mesh.material as MeshStandardMaterial;
      mat.color.setHex(col);
      mat.emissive.setHex(col);
    }
  }

  private createEnemyMesh(type: EnemyData['type']): Group {
    const group = new Group();

    if (type === 'coily') {
      // Coily: snake-like body — stacked spheres + pyramid head
      const bodyColor = 0xaa00ff;
      for (let i = 0; i < 3; i++) {
        const segGeo = new SphereGeometry(CUBE_SIZE * (0.2 - i * 0.03), 8, 8);
        const segMat = new MeshStandardMaterial({
          color: new Color(bodyColor),
          emissive: new Color(bodyColor),
          emissiveIntensity: 0.5,
        });
        const seg = new Mesh(segGeo, segMat);
        seg.position.y = i * 0.12;
        group.add(seg);
      }
      // Eyes — two tiny white spheres
      const eyeGeo = new SphereGeometry(0.04, 6, 6);
      const eyeMat = new MeshStandardMaterial({
        color: new Color(0xff4444),
        emissive: new Color(0xff4444),
        emissiveIntensity: 0.8,
      });
      const leftEye = new Mesh(eyeGeo, eyeMat);
      leftEye.position.set(-0.06, 0.28, 0.08);
      group.add(leftEye);
      const rightEye = new Mesh(eyeGeo, eyeMat);
      rightEye.position.set(0.06, 0.28, 0.08);
      group.add(rightEye);
    } else if (type === 'slick') {
      // Slick: flat wide disc shape
      const geo = new CylinderGeometry(CUBE_SIZE * 0.3, CUBE_SIZE * 0.25, 0.1, 10);
      const mat = new MeshStandardMaterial({
        color: new Color(0x00ff44),
        emissive: new Color(0x00ff44),
        emissiveIntensity: 0.5,
      });
      const body = new Mesh(geo, mat);
      body.position.y = 0.05;
      group.add(body);
      // Antennae
      const antGeo = new CylinderGeometry(0.01, 0.01, 0.15, 4);
      const antMat = new MeshStandardMaterial({
        color: new Color(0x44ff88),
        emissive: new Color(0x44ff88),
        emissiveIntensity: 0.6,
      });
      const antL = new Mesh(antGeo, antMat);
      antL.position.set(-0.06, 0.18, 0);
      antL.rotation.z = 0.3;
      group.add(antL);
      const antR = new Mesh(antGeo, antMat);
      antR.position.set(0.06, 0.18, 0);
      antR.rotation.z = -0.3;
      group.add(antR);
    } else {
      // Sam: cubic body with glowing core
      const geo = new BoxGeometry(CUBE_SIZE * 0.35, CUBE_SIZE * 0.35, CUBE_SIZE * 0.35);
      const mat = new MeshStandardMaterial({
        color: new Color(0x4488ff),
        emissive: new Color(0x4488ff),
        emissiveIntensity: 0.4,
        transparent: true,
        opacity: 0.8,
      });
      const body = new Mesh(geo, mat);
      body.position.y = 0.1;
      group.add(body);
      // Inner glow
      const coreGeo = new SphereGeometry(CUBE_SIZE * 0.15, 6, 6);
      const coreMat = new MeshBasicMaterial({
        color: new Color(0x88ccff),
        transparent: true,
        opacity: 0.6,
        blending: AdditiveBlending,
      });
      const core = new Mesh(coreGeo, coreMat);
      core.position.y = 0.1;
      group.add(core);
    }

    return group;
  }

  private spawnEnemy() {
    const types: EnemyData['type'][] = state.mode === 'zen' ? [] :
      state.difficulty === 'easy' ? ['coily'] :
      state.difficulty === 'hard' ? ['coily', 'slick', 'sam', 'coily'] :
      ['coily', 'slick', 'sam'];
    if (types.length === 0) return;
    if (state.enemies.length >= (state.difficulty === 'hard' ? 4 : 2)) return;
    const type = types[Math.floor(Math.random() * types.length)];
    const startCol = Math.floor(Math.random() * 2);
    const enemy: EnemyData = {
      type,
      row: 0,
      col: startCol,
      active: true,
      isEgg: type === 'coily',
      moveTimer: 0,
    };
    const id = this.enemyIdCounter++;
    state.enemies.push(enemy);
    const group = this.createEnemyMesh(type);
    const pos = cubePos(0, startCol);
    group.position.set(pos.x, pos.y + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.3, pos.z);
    this.scene.add(group);
    this.enemyMeshes.set(id, group);
    emitAudio('enemy_spawn');
  }

  private moveEnemies(delta: number) {
    if (state.freezeActive) return;

    const speed = state.difficulty === 'easy' ? 2.5 : state.difficulty === 'hard' ? 1.2 : 1.8;
    const keysToRemove: number[] = [];
    let enemyIdx = 0;
    const meshKeys = Array.from(this.enemyMeshes.keys());

    for (let i = 0; i < state.enemies.length; i++) {
      const enemy = state.enemies[i];
      if (!enemy.active) continue;
      enemy.moveTimer += delta;
      if (enemy.moveTimer < speed) { enemyIdx++; continue; }
      enemy.moveTimer = 0;

      if (enemy.type === 'coily') {
        if (enemy.isEgg) {
          const dc = Math.random() > 0.5 ? 1 : 0;
          enemy.row++;
          enemy.col += dc;
          if (enemy.row >= PYRAMID_ROWS) {
            enemy.active = false;
            const meshKey = meshKeys[enemyIdx];
            if (meshKey !== undefined) keysToRemove.push(meshKey);
          } else if (enemy.row >= 2) {
            enemy.isEgg = false;
          }
        } else {
          const dr = state.playerRow > enemy.row ? 1 : state.playerRow < enemy.row ? -1 : 0;
          const dc = state.playerCol > enemy.col ? 1 : state.playerCol < enemy.col ? -1 : 0;
          const newRow = enemy.row + dr;
          const newCol = enemy.col + dc;
          if (isValidCube(newRow, newCol)) {
            enemy.row = newRow;
            enemy.col = newCol;
          } else {
            if (dr !== 0 && isValidCube(enemy.row + dr, enemy.col)) {
              enemy.row += dr;
            }
          }
        }
      } else {
        const dc = Math.random() > 0.5 ? 1 : 0;
        enemy.row++;
        enemy.col += dc;
        if (!isValidCube(enemy.row, enemy.col)) {
          enemy.active = false;
          const meshKey = meshKeys[enemyIdx];
          if (meshKey !== undefined) keysToRemove.push(meshKey);
        } else {
          const cube = getCube(enemy.row, enemy.col);
          if (cube && cube.colorState > 0) {
            cube.colorState = 0;
          }
        }
      }

      if (enemy.active) {
        const meshKey = meshKeys[enemyIdx];
        const group = meshKey !== undefined ? this.enemyMeshes.get(meshKey) : undefined;
        if (group) {
          const pos = cubePos(enemy.row, enemy.col);
          group.position.set(pos.x, pos.y + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.3, pos.z);
        }
      }
      enemyIdx++;
    }

    for (const key of keysToRemove) {
      const group = this.enemyMeshes.get(key);
      if (group) this.scene.remove(group);
      this.enemyMeshes.delete(key);
    }
    state.enemies = state.enemies.filter(e => e.active);
  }

  private checkCollisions() {
    for (const enemy of state.enemies) {
      if (!enemy.active) continue;
      if (enemy.row === state.playerRow && enemy.col === state.playerCol) {
        if (state.shieldActive) {
          // Shield absorbs the hit, enemy is destroyed
          state.shieldActive = false;
          enemy.active = false;
          state.score += 500;
          state.stats.enemiesDefeated++;
          emitAudio('enemy_die');
          const pos = cubePos(enemy.row, enemy.col);
          emitEffect({ type: 'enemy_die', x: pos.x, y: pos.y + 0.5, z: pos.z });
          this.checkAchievement('defeat_coily');
        } else {
          this.playerDeath();
        }
        return;
      }
    }
    if (!isValidCube(state.playerRow, state.playerCol)) {
      if (state.shieldActive) {
        state.shieldActive = false;
        state.playerRow = 0;
        state.playerCol = 0;
        state.hopping = false;
      } else {
        this.playerDeath();
      }
    }
  }

  private playerDeath() {
    if (state.deathAnimating || state.gameOver) return;
    state.lives--;
    state.deathAnimating = true;
    state.deathTimer = 1.0;
    this.deathsThisRound++;
    state.combo = 0;
    state.comboTimer = 0;
    const pos = cubePos(state.playerRow, state.playerCol);
    emitAudio('death');
    emitEffect({ type: 'death', x: pos.x, y: pos.y + 0.5, z: pos.z });
    if (state.lives <= 0) {
      state.gameOver = true;
    }
  }

  private respawnPlayer() {
    state.deathAnimating = false;
    if (state.gameOver) {
      if (state.score > state.stats.highScore) {
        state.stats.highScore = state.score;
        saveStats(state.stats);
      }
      state.screen = 'results';
      return;
    }
    state.playerRow = 0;
    state.playerCol = 0;
    state.hopping = false;
    state.enemies = [];
    this.clearEnemyMeshes();
    state.enemySpawnTimer = 0;
  }

  // Power-up spawning
  private trySpawnPowerUp() {
    if (state.powerUps.length >= 1) return; // Max 1 power-up at a time
    if (state.round < 2 && state.mode !== 'zen') return; // No power-ups in round 1

    const availableCubes = state.cubes.filter(c =>
      c.colorState < c.targetState &&
      !(c.row === state.playerRow && c.col === state.playerCol)
    );
    if (availableCubes.length === 0) return;

    const target = availableCubes[Math.floor(Math.random() * availableCubes.length)];
    const types: PowerUpType[] = ['shield', 'scoreboost', 'freeze'];
    const type = types[Math.floor(Math.random() * types.length)];

    state.powerUps.push({
      type,
      row: target.row,
      col: target.col,
      active: true,
      pulsePhase: 0,
    });

    // Create visual
    const group = new Group();
    const pos = cubePos(target.row, target.col);
    const color = POWER_UP_COLORS[type];

    const coreGeo = new SphereGeometry(0.1, 8, 8);
    const coreMat = new MeshBasicMaterial({
      color: new Color(color),
      transparent: true,
      opacity: 0.9,
      blending: AdditiveBlending,
    });
    const core = new Mesh(coreGeo, coreMat);
    group.add(core);

    // Orbiting ring
    const ringGeo = new CylinderGeometry(0.15, 0.15, 0.02, 12);
    const ringMat = new MeshBasicMaterial({
      color: new Color(color),
      transparent: true,
      opacity: 0.5,
      blending: AdditiveBlending,
    });
    const ring = new Mesh(ringGeo, ringMat);
    group.add(ring);

    group.position.set(pos.x, pos.y + PILLAR_HEIGHT * 0.5 + 0.4, pos.z);
    this.scene.add(group);
    this.powerUpMeshes.set(`${target.row}_${target.col}`, group);
    emitAudio('powerup_spawn');
  }

  private checkPowerUpCollection() {
    for (let i = state.powerUps.length - 1; i >= 0; i--) {
      const pu = state.powerUps[i];
      if (!pu.active) continue;
      if (pu.row === state.playerRow && pu.col === state.playerCol) {
        pu.active = false;
        const key = `${pu.row}_${pu.col}`;
        const mesh = this.powerUpMeshes.get(key);
        if (mesh) {
          this.scene.remove(mesh);
          this.powerUpMeshes.delete(key);
        }

        // Apply power-up
        switch (pu.type) {
          case 'shield':
            state.shieldActive = true;
            break;
          case 'scoreboost':
            state.scoreBoostActive = true;
            state.activePowerUp = { type: 'scoreboost', timeLeft: 10 };
            break;
          case 'freeze':
            state.freezeActive = true;
            state.activePowerUp = { type: 'freeze', timeLeft: 5 };
            break;
        }

        emitAudio('powerup_collect');
        emitEffect({ type: 'hop_land', x: cubePos(pu.row, pu.col).x, y: cubePos(pu.row, pu.col).y + 0.5, z: cubePos(pu.row, pu.col).z });
        state.score += 100;
        state.powerUps.splice(i, 1);
      }
    }
  }

  private updatePowerUpTimers(delta: number) {
    if (state.activePowerUp) {
      state.activePowerUp.timeLeft -= delta;
      if (state.activePowerUp.timeLeft <= 0) {
        if (state.activePowerUp.type === 'freeze') {
          state.freezeActive = false;
        } else if (state.activePowerUp.type === 'scoreboost') {
          state.scoreBoostActive = false;
        }
        state.activePowerUp = null;
      }
    }

    // Animate power-up meshes
    for (const [, group] of this.powerUpMeshes) {
      group.rotation.y += delta * 2;
      group.position.y += Math.sin(Date.now() * 0.003) * delta * 0.2;
    }
  }

  tryHop(dr: number, dc: number) {
    if (state.hopping || state.deathAnimating || state.roundComplete || state.screen !== 'playing') return;
    const newRow = state.playerRow + dr;
    const newCol = state.playerCol + dc;

    if (!isValidCube(newRow, newCol)) {
      if (state.discLeft && newCol < 0 && newRow >= 2 && newRow <= 4) {
        state.discLeft = false;
        state.discUsed = true;
        this.useDisc();
        return;
      }
      if (state.discRight && newCol > newRow && newRow >= 2 && newRow <= 4) {
        state.discRight = false;
        state.discUsed = true;
        this.useDisc();
        return;
      }
      // Fall off
      state.hopFromRow = state.playerRow;
      state.hopFromCol = state.playerCol;
      state.hopToRow = newRow;
      state.hopToCol = newCol;
      state.hopping = true;
      state.hopProgress = 0;
      return;
    }

    state.hopFromRow = state.playerRow;
    state.hopFromCol = state.playerCol;
    state.hopToRow = newRow;
    state.hopToCol = newCol;
    state.hopping = true;
    state.hopProgress = 0;
    if (state.mode === 'challenge') state.hopsRemaining--;
    state.totalHops++;
    state.stats.cubesHopped++;
    emitAudio('hop');
    this.checkAchievement('first_hop');
    if (state.stats.cubesHopped >= 100) this.checkAchievement('cubes_100');
  }

  private useDisc() {
    state.playerRow = 0;
    state.playerCol = 0;
    state.hopping = false;
    for (const enemy of state.enemies) {
      if (enemy.type === 'coily' && enemy.active) {
        enemy.active = false;
        state.score += 500;
        state.stats.enemiesDefeated++;
        emitAudio('enemy_die');
        this.checkAchievement('defeat_coily');
      }
    }
    this.checkAchievement('disc_use');
    emitAudio('disc_use');
  }

  private completeHop() {
    state.playerRow = state.hopToRow;
    state.playerCol = state.hopToCol;
    state.hopping = false;

    if (!isValidCube(state.playerRow, state.playerCol)) {
      this.playerDeath();
      return;
    }

    const cube = getCube(state.playerRow, state.playerCol);
    if (cube && cube.colorState < cube.targetState) {
      cube.colorState++;
      // Combo scoring
      state.combo++;
      state.comboTimer = 3.0;
      if (state.combo > state.maxCombo) state.maxCombo = state.combo;
      const comboMult = Math.min(state.combo, 10);
      const baseScore = 25;
      const scoreGain = baseScore * (state.scoreBoostActive ? 2 : 1) * comboMult;
      state.score += scoreGain;
      if (comboMult >= 3) {
        emitAudio('combo');
      }
      emitAudio('color_change');
      this.updateCubeColors();
    } else {
      // Hopped on already-complete cube — combo resets
      state.combo = 0;
      state.comboTimer = 0;
    }

    const pos = cubePos(state.playerRow, state.playerCol);
    emitEffect({ type: 'hop_land', x: pos.x, y: pos.y + PILLAR_HEIGHT * 0.5, z: pos.z });

    this.checkPowerUpCollection();
    this.checkCollisions();

    if (allCubesComplete()) {
      this.completeRound();
    }
  }

  private completeRound() {
    state.roundComplete = true;
    const roundBonus = 1000 + (state.combo * 50);
    state.score += roundBonus;
    state.round++;
    state.stats.roundsCleared++;
    saveStats(state.stats);
    emitAudio('round_complete');
    emitEffect({ type: 'round_complete' });

    if (this.deathsThisRound === 0) this.checkAchievement('perfect');
    this.checkAchievement('round_1');
    if (state.stats.roundsCleared >= 5) this.checkAchievement('round_5');
    if (state.stats.roundsCleared >= 10) this.checkAchievement('round_10');
    if (state.stats.roundsCleared >= 20) this.checkAchievement('round_20');
    if (state.mode === 'speed') this.checkAchievement('speed_clear');
    if (state.mode === 'challenge') this.checkAchievement('challenge_clear');

    setTimeout(() => {
      if (state.screen === 'playing') {
        this.startRound();
      }
    }, 2000);
  }

  private checkAchievement(id: string) {
    const ach = state.achievements.find(a => a.id === id);
    if (ach && !ach.unlocked) {
      ach.unlocked = true;
      saveAchievements(state.achievements);
    }
  }

  private updatePlayerMesh(time: number) {
    this.playerMesh.visible = state.screen === 'playing';
    this.playerGlowMesh.visible = state.screen === 'playing';
    if (state.screen !== 'playing') return;

    if (state.deathAnimating) {
      this.playerMesh.position.y -= 0.05;
      const mat = this.playerMesh.material as MeshStandardMaterial;
      mat.opacity = Math.max(0, state.deathTimer);
      mat.transparent = true;
      this.playerGlowMesh.visible = false;
      return;
    }

    // Shield visual — make player glow blue
    if (state.shieldActive) {
      const glowMat = this.playerGlowMesh.material as MeshBasicMaterial;
      glowMat.color.setHex(0x44aaff);
      glowMat.opacity = 0.25 + Math.sin(time * 5) * 0.1;
    } else {
      const cs = COLOR_SCHEMES[state.colorScheme];
      const glowMat = this.playerGlowMesh.material as MeshBasicMaterial;
      glowMat.color.setHex(cs.target);
      glowMat.opacity = 0.1 + Math.sin(time * 2) * 0.05;
    }

    // Combo glow — player pulses with combo streak
    if (state.combo >= 3) {
      const mat = this.playerMesh.material as MeshStandardMaterial;
      mat.emissiveIntensity = 0.6 + Math.sin(time * 8) * 0.3;
    } else {
      const mat = this.playerMesh.material as MeshStandardMaterial;
      mat.emissiveIntensity = 0.6;
    }

    if (state.hopping) {
      const t = state.hopProgress;
      const fromPos = cubePos(state.hopFromRow, state.hopFromCol);
      const toPos = cubePos(state.hopToRow, state.hopToCol);
      const x = fromPos.x + (toPos.x - fromPos.x) * t;
      const z = fromPos.z + (toPos.z - fromPos.z) * t;
      const baseY = fromPos.y + (toPos.y - fromPos.y) * t;
      const arc = Math.sin(t * Math.PI) * 0.8;
      const py = baseY + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.35 + arc;
      this.playerMesh.position.set(x, py, z);
      this.playerGlowMesh.position.copy(this.playerMesh.position);
    } else {
      const pos = cubePos(state.playerRow, state.playerCol);
      const py = pos.y + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.35;
      this.playerMesh.position.set(pos.x, py, pos.z);
      this.playerGlowMesh.position.copy(this.playerMesh.position);
    }
  }

  private updateCamera(delta: number) {
    // Smooth camera tracking based on player position
    const playerPos = cubePos(state.playerRow, state.playerCol);
    const offsetX = playerPos.x * 0.15;
    const offsetZ = playerPos.z * 0.1;
    this.cameraTarget.set(2 + offsetX, 5.5 - state.playerRow * 0.05, 5 + offsetZ);
    this.cameraLookTarget.set(offsetX * 0.5, 1.2, 1.2 + offsetZ * 0.3);

    const cam = this.camera;
    const lerpFactor = 1 - Math.pow(0.05, delta);
    cam.position.lerp(this.cameraTarget, lerpFactor);

    // Simple look-at interpolation
    const currentLook = new Vector3();
    cam.getWorldDirection(currentLook);
    currentLook.multiplyScalar(5).add(cam.position);
    currentLook.lerp(this.cameraLookTarget, lerpFactor);
    cam.lookAt(this.cameraLookTarget);
  }

  private animateEnemies(time: number) {
    const meshKeys = Array.from(this.enemyMeshes.keys());
    let enemyIdx = 0;
    for (const enemy of state.enemies) {
      if (!enemy.active) continue;
      const meshKey = meshKeys[enemyIdx];
      const group = meshKey !== undefined ? this.enemyMeshes.get(meshKey) : undefined;
      if (group) {
        // Coily bobs up/down, Slick/Sam rotate
        if (enemy.type === 'coily') {
          group.position.y += Math.sin(time * 3 + enemyIdx) * 0.001;
        } else {
          group.rotation.y = time * 2;
        }

        // Freeze visual — enemies turn blue-white
        if (state.freezeActive) {
          group.traverse(child => {
            if (child instanceof Mesh) {
              const mat = child.material;
              if (mat instanceof MeshStandardMaterial || mat instanceof MeshBasicMaterial) {
                mat.color.lerp(new Color(0x88ccff), 0.1);
              }
            }
          });
        }
      }
      enemyIdx++;
    }
  }

  update(delta: number, time: number) {
    if (state.screen !== 'playing') {
      this.playerMesh.visible = false;
      this.playerGlowMesh.visible = false;
      for (const [, g] of this.enemyMeshes) g.visible = false;
      for (const d of this.discMeshes) d.visible = false;
      for (const [, g] of this.powerUpMeshes) g.visible = false;
      return;
    }

    this.playerMesh.visible = true;
    this.playerGlowMesh.visible = true;
    for (const [, g] of this.enemyMeshes) g.visible = true;
    for (const [, g] of this.powerUpMeshes) g.visible = true;

    // Handle pending input
    if (state.pendingInput && !state.hopping && !state.deathAnimating && !state.roundComplete) {
      this.tryHop(state.pendingInput.dr, state.pendingInput.dc);
      state.pendingInput = null;
    }

    // Hop animation
    if (state.hopping) {
      state.hopProgress += delta / HOP_DURATION;
      if (state.hopProgress >= 1) {
        state.hopProgress = 1;
        this.completeHop();
      }
    }

    // Death animation
    if (state.deathAnimating) {
      state.deathTimer -= delta;
      if (state.deathTimer <= 0) {
        this.respawnPlayer();
      }
    }

    // Round announce timer
    if (state.roundAnnounceTimer > 0) {
      state.roundAnnounceTimer -= delta;
    }

    // Combo timer decay
    if (state.comboTimer > 0) {
      state.comboTimer -= delta;
      if (state.comboTimer <= 0) {
        state.combo = 0;
        state.comboTimer = 0;
      }
    }

    // Enemy spawning
    if (!state.deathAnimating && !state.roundComplete && state.mode !== 'zen') {
      state.enemySpawnTimer += delta;
      const spawnInterval = state.difficulty === 'easy' ? 8 : state.difficulty === 'hard' ? 4 : 6;
      if (state.enemySpawnTimer >= spawnInterval) {
        state.enemySpawnTimer = 0;
        this.spawnEnemy();
      }
    }

    // Power-up spawning
    if (!state.deathAnimating && !state.roundComplete) {
      state.powerUpSpawnTimer += delta;
      const puInterval = state.difficulty === 'easy' ? 15 : state.difficulty === 'hard' ? 25 : 20;
      if (state.powerUpSpawnTimer >= puInterval) {
        state.powerUpSpawnTimer = 0;
        this.trySpawnPowerUp();
      }
    }

    // Move enemies + animations
    this.moveEnemies(delta);
    this.animateEnemies(time);
    this.updateCubeColors();
    this.updatePowerUpTimers(delta);

    // Speed mode timer
    if (state.mode === 'speed' && !state.deathAnimating && !state.roundComplete) {
      state.timer -= delta;
      if (state.timer <= 0) {
        state.timer = 0;
        state.gameOver = true;
        state.deathAnimating = true;
        state.deathTimer = 1.0;
      }
    }

    // Challenge mode hops
    if (state.mode === 'challenge' && state.hopsRemaining <= 0 && !state.roundComplete) {
      state.gameOver = true;
      state.deathAnimating = true;
      state.deathTimer = 1.0;
    }

    // Score achievements
    if (state.score >= 10000) this.checkAchievement('score_10k');
    if (state.score >= 50000) this.checkAchievement('score_50k');
    if (state.score >= 100000) this.checkAchievement('score_100k');
    if (state.stats.enemiesDefeated >= 10) this.checkAchievement('defeat_10');
    if (state.stats.enemiesDefeated >= 50) this.checkAchievement('defeat_50');
    if (state.stats.gamesPlayed >= 10) this.checkAchievement('play_10');
    if (state.stats.gamesPlayed >= 50) this.checkAchievement('play_50');

    if (state.mode === 'zen' && state.stats.roundsCleared >= 5) {
      this.checkAchievement('zen_5');
    }

    // Check collisions
    if (!state.hopping && !state.deathAnimating) {
      this.checkCollisions();
    }

    this.updatePlayerMesh(time);
    this.positionDiscs();
    this.updateCamera(delta);

    // Rotate discs
    for (const d of this.discMeshes) {
      if (d.visible) d.rotation.y += delta * 3;
    }
  }
